mapper.select:
SELECT 
FROM   tb_com_cd

    AND grp_cd = #{grpCd}
    AND cd     = #{cd}
    AND cd_nm  LIKE CONCAT('%', #{cdNm}, '%')
    AND use_at = #{useAt}

ORDER BY grp_cd, sort_ord, cd

SELECT 
FROM   tb_com_cd
WHERE  grp_cd = #{grpCd}
  AND  cd     = #{cd}

mapper.update:
UPDATE tb_com_cd
SET cd_nm    = #{cdNm},
    dc       = #{dc},
    sort_ord = #{sortOrd},
    use_at   = #{useAt},
    etc_1    = #{etc1},
    mdfcn_dt = CURRENT_TIMESTAMP,
    mdfr     = #{mdfr}
WHERE grp_cd = #{grpCd}
  AND cd     = #{cd}

mapper.delete:
DELETE FROM tb_com_cd
WHERE grp_cd = #{grpCd}
  AND cd     = #{cd}
